CREATE OR REPLACE FUNCTION public.hasten_crops(p_world uuid, p_uid uuid)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare n int; m int;
begin
  with bumped as (
    update crop c set stage = c.stage + 1, stage_at = now(), tended_now = false
     where c.world_id = p_world and c.stage < crop_ripe() and not c.still and on_my_deed(p_world, p_uid, c.x, c.y)
