     where c.world_id = p_world and pl.id = c.placed and c.stage < crop_ripe()
       and on_my_deed(p_world, p_uid, pl.x, pl.y)
    returning 1
  ) select count(*)::int into m from bumped;
  return n + m;
end $function$
